package local.tvmorph.tv;
import android.app.*;import android.os.*;import android.content.*;import android.media.tv.*;import android.widget.*;import android.view.*;
/** Uses Android's public TV Input Framework when firmware exposes no ACTION_VIEW handler. */
public class InputActivity extends Activity {
 private TvView tv;private TextView message;private LinearLayout panel;private Button primary;private boolean videoAvailable;private int revealKey;private String inputId="";private final Handler handler=new Handler(Looper.getMainLooper());
 private String t(String ar,String en){String lang=UiSettings.language(this);if(lang.equals("ar"))return ar;int index=lang.equals("fr")?0:lang.equals("zh")?1:lang.equals("ja")?2:-1;if(index<0)return en;java.util.Map<String,String[]> words=new java.util.HashMap<>();words.put("Change input",new String[]{"Changer d’entrée","切换输入","入力を変更"});words.put("Retry",new String[]{"Réessayer","重试","再試行"});words.put("TV settings",new String[]{"Réglages TV","电视设置","テレビ設定"});words.put("Back to Morph TV",new String[]{"Retour à Morph TV","返回 Morph TV","Morph TV に戻る"});words.put("The firmware did not open this input inside the app. Try TV settings.",new String[]{"Le système ne permet pas cette entrée dans l’application. Essayez les réglages TV.","系统无法在应用内打开此输入。请尝试电视设置。","アプリ内で入力を開けません。テレビ設定をお試しください。"});words.put("Input disconnected. Try again.",new String[]{"Entrée déconnectée. Réessayez.","输入已断开，请重试。","入力が切断されました。再試行してください。"});words.put("Input playing · Back returns to Morph TV",new String[]{"Entrée en cours · Retour vers Morph TV","输入播放中 · 返回键回到 Morph TV","入力再生中 · 戻るで Morph TV へ"});words.put("Waiting for input signal. Check the connected device and cable.",new String[]{"En attente du signal. Vérifiez l’appareil et le câble.","正在等待输入信号。请检查设备和连接线。","入力信号を待っています。機器とケーブルをご確認ください。"});words.put("Opening input…",new String[]{"Ouverture de l’entrée…","正在打开输入…","入力を開いています…"});words.put("Firmware blocked this input. Use TV settings.",new String[]{"Le système bloque cette entrée. Utilisez les réglages TV.","系统阻止了此输入。请使用电视设置。","この入力はシステムに拒否されました。テレビ設定をご利用ください。"});words.put("No TV inputs are exposed to apps. Open TV settings.",new String[]{"Aucune entrée accessible aux applications. Ouvrez les réglages TV.","应用无法访问电视输入。请打开电视设置。","アプリが利用できる入力がありません。テレビ設定を開いてください。"});words.put("Choose input",new String[]{"Choisir une entrée","选择输入","入力を選択"});words.put("Back",new String[]{"Retour","返回","戻る"});return words.containsKey(en)?words.get(en)[index]:en;}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0xff050a12);tv=new TvView(this);root.addView(tv,new FrameLayout.LayoutParams(-1,-1));panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(20,12,20,12);panel.setBackgroundColor(0xbb102237);message=new TextView(this);message.setTextColor(0xffffffff);message.setTextSize(20);panel.addView(message);LinearLayout buttons=new LinearLayout(this);add(buttons,t("تبديل المدخل","Change input"),this::choose);add(buttons,t("إعادة المحاولة","Retry"),this::tune);add(buttons,t("إعدادات التلفزيون","TV settings"),()->SystemSettingsTools.openSystem(this));add(buttons,t("رجوع إلى Morph TV","Back to Morph TV"),this::finish);panel.addView(buttons);root.addView(panel,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));setContentView(root);
 tv.setCallback(new TvView.TvInputCallback(){@Override public void onConnectionFailed(String id){videoAvailable=false;showPanel();message.setText(t("النظام لم يسمح بفتح المدخل داخل التطبيق. جرّب إعدادات التلفزيون.","The firmware did not open this input inside the app. Try TV settings."));}@Override public void onDisconnected(String id){videoAvailable=false;showPanel();message.setText(t("انقطع اتصال المدخل. جرّب إعادة المحاولة.","Input disconnected. Try again."));}@Override public void onVideoAvailable(String id){videoAvailable=true;showPanel();scheduleHide();message.setText(t("المدخل يعمل · رجوع للعودة إلى Morph TV","Input playing · Back returns to Morph TV"));}@Override public void onVideoUnavailable(String id,int reason){videoAvailable=false;showPanel();message.setText(t("في انتظار إشارة المدخل. تأكد من تشغيل الجهاز والكابل.","Waiting for input signal. Check the connected device and cable."));}});inputId=getIntent().getStringExtra("inputId");if(inputId==null)inputId="";}
 private void add(LinearLayout row,String title,Runnable action){Button button=new Button(this);button.setText(title);if(primary==null)primary=button;button.setOnFocusChangeListener((v,focused)->{if(focused)scheduleHide();});button.setOnClickListener(v->{action.run();scheduleHide();});row.addView(button,new LinearLayout.LayoutParams(0,-2,1));}
 private void tune(){videoAvailable=false;showPanel();try{TvInputManager manager=(TvInputManager)getSystemService(TV_INPUT_SERVICE);if(manager==null||!physical(inputId)){choose();return;}message.setText(t("جاري فتح المدخل…","Opening input…"));tv.tune(inputId,TvContract.buildChannelUriForPassthroughInput(inputId));}catch(RuntimeException e){message.setText(t("النظام منع فتح المدخل. استخدم إعدادات التلفزيون.","Firmware blocked this input. Use TV settings."));}}
 private boolean physical(String id){try{org.json.JSONObject source=AndroidInputs.find(this,id);return source!=null&&source.optBoolean("passthrough");}catch(Exception e){return false;}}
 private void choose(){try{org.json.JSONArray all=AndroidInputs.collect(this);java.util.List<org.json.JSONObject> rows=new java.util.ArrayList<>();for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optBoolean("passthrough"))rows.add(all.getJSONObject(i));if(rows.isEmpty()){message.setText(t("الشاشة لا تعرض مداخل متاحة للتطبيق. افتح إعدادات التلفزيون.","No TV inputs are exposed to apps. Open TV settings."));return;}String[] labels=new String[rows.size()];for(int i=0;i<labels.length;i++)labels[i]=rows.get(i).optString("title");new AlertDialog.Builder(this).setTitle(t("اختار المدخل","Choose input")).setItems(labels,(d,w)->{inputId=rows.get(w).optString("id");tune();}).setNegativeButton(t("رجوع","Back"),null).show();}catch(Exception e){message.setText(t("النظام منع فتح المدخل. استخدم إعدادات التلفزيون.","Firmware blocked this input. Use TV settings."));}}
 private final Runnable hidePanel=()->{if(videoAvailable&&hasWindowFocus()){panel.setVisibility(View.GONE);tv.requestFocus();}};
 private void scheduleHide(){handler.removeCallbacks(hidePanel);if(videoAvailable)handler.postDelayed(hidePanel,4000);}
 private void showPanel(){if(panel!=null){panel.setVisibility(View.VISIBLE);if(primary!=null&&!panel.hasFocus())primary.requestFocus();}scheduleHide();}
 @Override public boolean dispatchKeyEvent(KeyEvent event){int key=event.getKeyCode();if(revealKey!=0&&key==revealKey){if(event.getAction()==KeyEvent.ACTION_UP)revealKey=0;return true;}boolean reveal=key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER||key==KeyEvent.KEYCODE_MENU||key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN||key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT;if(reveal&&panel!=null){if(panel.getVisibility()!=View.VISIBLE){if(event.getAction()==KeyEvent.ACTION_DOWN){revealKey=key;showPanel();}return true;}if(event.getAction()==KeyEvent.ACTION_DOWN)scheduleHide();}return super.dispatchKeyEvent(event);}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)scheduleHide();else handler.removeCallbacks(hidePanel);}
 @Override protected void onResume(){super.onResume();ParentalTimer.window(this,getPackageName());handler.postDelayed(this::tune,100);}
 @Override protected void onPause(){handler.removeCallbacksAndMessages(null);tv.reset();super.onPause();}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);tv.reset();super.onDestroy();}
}
